cat > "$DIR/common.py" << 'PYEOF'
import glob
import json
import os
import re
import shutil
import subprocess
import time

DIR = os.environ.get("CATALOG_DIR", "/storage/catalog")
ROMS = os.environ.get("ROMS_DIR", "/storage/roms")
LOG = os.path.join(DIR, "log.txt")
IMG = os.path.join(DIR, "img")
SIZES = os.path.join(DIR, "sizes.json")

NAMES = {
    "nes": "NES", "snes": "SNES", "atarilynx": "Atari Lynx", "atari2600": "Atari 2600",
    "gba": "Game Boy Advance", "gbc": "Game Boy Color", "genesis": "Sega Genesis",
    "mastersystem": "Sega Master System", "c64": "Commodore 64", "zxspectrum": "Sinclair ZX Spectrum",
    "n64": "Nintendo 64",
}
EXT = {
    "nes": ".nes", "snes": ".sfc", "atarilynx": ".lnx", "atari2600": ".a26", "gba": ".gba",
    "gbc": ".gbc", "genesis": ".md", "mastersystem": ".sms", "c64": ".d64", "zxspectrum": ".tap", "n64": ".z64",
}
VALID = {
    "nes": (".nes", ".unf", ".unif", ".fds"),
    "snes": (".sfc", ".smc", ".fig", ".swc", ".bs", ".st", ".bin"),
    "atarilynx": (".lnx", ".lyx", ".o"),
    "atari2600": (".a26", ".bin", ".a78"),
    "gba": (".gba", ".bin", ".agb"),
    "gbc": (".gbc", ".gb", ".cgb"),
    "genesis": (".bin", ".md", ".smd", ".gen"),
    "mastersystem": (".sms", ".bin"),
    "c64": (".d64", ".prg", ".tap", ".t64", ".crt", ".d71", ".d81", ".g64", ".x64"),
    "zxspectrum": (".tap", ".tzx", ".z80", ".sna", ".szx"),
    "n64": (".z64", ".n64", ".v64"),
}
CURL_FLAGS = ["-L", "-s", "-f", "--connect-timeout", "15", "--speed-time", "30", "--speed-limit", "1000"]


def log(m):
    os.makedirs(DIR, exist_ok=True)
    with open(LOG, "a") as f:
        f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + m + "\n")


def slug(t):
    return re.sub(r"[^a-z0-9]+", "-", t.lower()).strip("-")


def clean(t):
    return re.sub(r'[\\/:*?"<>|]', "", t).strip()


def show(name, hold=0):
    # Draw a full-screen message image, the same way EmuELEC draws its own splash screens
    path = os.path.join(IMG, name + ".png")
    if not os.environ.get("CATALOG_NO_SCREEN") and os.path.exists(path):
        try:
            r = subprocess.run(
                ["ffplay", "-fs", "-loglevel", "error", "-nostats", "-autoexit", "-i", path],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=4)
            if r.returncode != 0:
                log("SCREEN: ffplay returned %d for %s" % (r.returncode, name))
        except subprocess.TimeoutExpired:
            log("SCREEN: ffplay timed out for " + name)
        except Exception as e:
            log("SCREEN: could not show %s (%s)" % (name, e))
    if hold:
        time.sleep(hold)


def reload_menu():
    # Restart EmulationStation so it sees the changes
    if os.environ.get("CATALOG_NO_RELOAD"):
        return
    subprocess.Popen(["systemctl", "restart", "emustation"], start_new_session=True)


def curl_rc(url, out, timeout=0):
    cmd = ["curl"] + CURL_FLAGS + (["-m", str(timeout)] if timeout else []) + ["-o", out, url]
    return subprocess.run(cmd).returncode


def error_image(rc):
    # curl exit codes: 6/7/28 = cannot resolve/connect/timeout, 22 = HTTP error (404...)
    if rc in (6, 7, 28):
        return "noint"
    if rc == 22:
        return "broken"
    return "fail"


def list_files():
    return sorted(glob.glob(os.path.join(DIR, "lists", "*.jsonl")))


def read_list(path):
    # yields (record, line_ok); bad lines are reported, never raised
    for line in open(path, encoding="utf-8", errors="ignore"):
        line = line.strip()
        if not line:
            continue
        try:
            j = json.loads(line)
            j["label"]
            j["system"]
            yield j, True
        except Exception:
            yield None, False


def load_sizes():
    try:
        return json.load(open(SIZES))
    except Exception:
        return {}


def size_of(rec, sizes):
    return int(rec.get("size") or sizes.get(rec["system"] + "/" + slug(rec["label"])) or 0)


def fmt_size(n):
    if not n:
        return ""
    if n < 1024 * 1024:
        return "%d KB" % max(1, round(n / 1024))
    return "%.1f MB" % (n / 1048576)


def known_exts(system):
    return {".zip", EXT.get(system, ".bin")} | set(VALID.get(system, ()))


def installed_paths(system, label):
    folder = os.path.join(ROMS, system)
    return [os.path.join(folder, label + e) for e in sorted(known_exts(system))
            if os.path.exists(os.path.join(folder, label + e))]


def free_bytes():
    if os.environ.get("CATALOG_FREE_BYTES"):
        return int(os.environ["CATALOG_FREE_BYTES"])
    os.makedirs(ROMS, exist_ok=True)
    return shutil.disk_usage(ROMS).free


def total_size(url, probe=False):
    # 1) HEAD request, 2) a 1-byte range request (reads the total from Content-Range),
    # 3) only when probe=True: download the file (max 30 MB) and measure it
    for extra in (["-I"], ["-r", "0-0", "-D", "-", "-o", "/dev/null"]):
        try:
            r = subprocess.run(["curl", "-s", "-L", "-m", "20"] + extra + [url],
                               stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
            head = r.stdout.decode("latin-1")
            m = re.findall(r"(?im)^content-range:\s*bytes\s+\d+-\d+/(\d+)", head)
            if m:
                return int(m[-1])
            m = re.findall(r"(?im)^content-length:\s*(\d+)", head)
            if m and int(m[-1]) > 1:
                return int(m[-1])
        except Exception:
            pass
    if probe:
        tmp = "/tmp/catalog_size_probe"
        try:
            rc = subprocess.run(["curl", "-s", "-f", "-L", "-m", "60", "--max-filesize", "31457280", "-o", tmp, url]).returncode
            if rc == 0 and os.path.exists(tmp):
                return os.path.getsize(tmp)
        except Exception:
            pass
        finally:
            if os.path.exists(tmp):
                os.remove(tmp)
    return 0


def resolve_url(rec):
    # returns (url, error_image). Entries with a "page" are resolved to the real download link.
    if rec.get("url"):
        return rec["url"], None
    tmp = "/tmp/catalog_page.html"
    rc = curl_rc(rec["page"], tmp, 30)
    if rc != 0:
        return None, error_image(rc)
    txt = open(tmp, encoding="utf-8", errors="ignore").read()
    m = re.search(r"download_file/(\d+)", txt)
    if not m:
        return None, "broken"
    return "https://www.zophar.net/download_file/" + m.group(1), None
PYEOF

cat > "$DIR/generate.py" << 'PYEOF'
import os
import shutil

from common import *

ROOT = os.path.join(ROMS, "ports_scripts", "Catalog")
DELETE_DIR = "Installed - select one to DELETE it"

shutil.rmtree(ROOT, ignore_errors=True)
os.makedirs(ROOT, exist_ok=True)
sizes = load_sizes()
total = skipped = installed = 0


def write_entry(folder, fname, command):
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, fname)
    with open(path, "w") as f:
        f.write("#!/bin/bash\n" + command + "\n")
    os.chmod(path, 0o755)


for path in list_files():
    for rec, ok in read_list(path):
        if not ok:
            skipped += 1
            continue
        system, label = rec["system"], clean(rec["label"])
        console = NAMES.get(system, system)
        size = fmt_size(size_of(rec, sizes))
        have = bool(installed_paths(system, label))
        fname = ("[Installed] " if have else "") + label + (" (%s)" % size if size else "") + ".sh"
        write_entry(os.path.join(ROOT, console), fname,
                    "python3 %s/download.py %s %s" % (DIR, system, slug(rec["label"])))
        total += 1
        if have:
            installed += 1
            write_entry(os.path.join(ROOT, DELETE_DIR), "%s - %s.sh" % (console, label),
                        "python3 %s/download.py delete %s %s" % (DIR, system, slug(rec["label"])))

write_entry(ROOT, "Update Catalog.sh", "python3 %s/update.py" % DIR)
print("%d entries created in %s (%d installed, %d invalid lines skipped)" % (total, ROOT, installed, skipped))
PYEOF

cat > "$DIR/download.py" << 'PYEOF'
import os
import re
import shutil
import subprocess
import sys
import time
import zipfile
from urllib.parse import unquote, urlparse

from common import *


def regenerate():
    subprocess.run([sys.executable, os.path.join(DIR, "generate.py")], stdout=subprocess.DEVNULL)


def fail(message, image="fail"):
    log(message)
    show(image, 3)
    reload_menu()


def find(system, key):
    path = os.path.join(DIR, "lists", system + ".jsonl")
    if os.path.exists(path):
        for rec, ok in read_list(path):
            if ok and slug(rec["label"]) == key:
                return rec
    return None


def fetch_with_progress(url, out, total):
    p = subprocess.Popen(["curl"] + CURL_FLAGS + ["-o", out, url])
    last = 0
    while p.poll() is None:
        if total and os.path.exists(out):
            step = min(90, int(os.path.getsize(out) * 100 / total) // 10 * 10)
            if step > last:
                show("p%03d" % step)
                last = step
        time.sleep(0.3)
    return p.returncode


def do_delete(system, key):
    rec = find(system, key)
    if not rec:
        log("NOT FOUND (delete): %s %s" % (system, key))
        return
    paths = installed_paths(system, clean(rec["label"]))
    for p in paths:
        os.remove(p)
    log("DELETED: %s (%d file)" % (clean(rec["label"]), len(paths)))
    regenerate()
    show("deleted", 2)
    reload_menu()


def main():
    if len(sys.argv) >= 4 and sys.argv[1] == "delete":
        return do_delete(sys.argv[2], sys.argv[3])
    system, key = sys.argv[1], sys.argv[2]
    rec = find(system, key)
    if not rec:
        return fail("NOT FOUND: %s %s" % (system, key))
    name = clean(rec["label"])
    dest = os.path.join(ROMS, system)
    os.makedirs(dest, exist_ok=True)
    if installed_paths(system, name):
        log("ALREADY INSTALLED: " + name)
        show("have", 2)
        reload_menu()
        return
    show("wait")
    url, err = resolve_url(rec)
    if not url:
        return fail("FAILED to find the download link of " + name, err)
    total = size_of(rec, load_sizes()) or total_size(url)
    if free_bytes() < (total or 0) + 30 * 1024 * 1024:
        return fail("NOT ENOUGH SPACE for %s (needs %s, free %s)" % (name, fmt_size(total), fmt_size(free_bytes())), "nospace")
    tmp = "/tmp/catalog_rom"
    if os.path.exists(tmp):
        os.remove(tmp)
    rc = fetch_with_progress(url, tmp, total)
    if rc != 0 or not os.path.exists(tmp) or os.path.getsize(tmp) == 0:
        return fail("FAILED download of %s (curl exit code %d)" % (name, rc), error_image(rc))
    with open(tmp, "rb") as f:
        head = f.read(512)
    if b"<html" in head.lower():
        os.remove(tmp)
        return fail("FAILED (got a web page instead of the game): " + name, "broken")
    url_ext = os.path.splitext(unquote(urlparse(url).path))[1].lower()
    if head[:2] == b"PK":
        ext = ".zip"
    elif url_ext in VALID.get(system, ()):
        ext = url_ext
    else:
        ext = EXT.get(system, ".bin")
    if ext == ".zip" and system in VALID:
        try:
            inside = zipfile.ZipFile(tmp).namelist()
        except Exception:
            os.remove(tmp)
            return fail("FAILED (damaged zip): " + name, "notrom")
        if not any(n.lower().endswith(VALID[system]) for n in inside):
            os.remove(tmp)
            return fail("NOT A %s ROM (zip contains: %s): %s" % (system, ", ".join(inside), name), "notrom")
    shutil.move(tmp, os.path.join(dest, name + ext))
    log("OK: %s -> %s/%s%s" % (name, system, name, ext))
    regenerate()
    show("p100")
    show("done", 2)
    reload_menu()


main()
PYEOF

cat > "$DIR/update.py" << 'PYEOF'
import os
import shutil
import subprocess
import sys
import time

from common import *


def buster(base):
    return "?t=%d" % int(time.time()) if base.startswith("http") else ""


def update_code(base):
    # Download the latest installer, check it, run it (it replaces the scripts, lists and images)
    tmp = "/tmp/catalog_installer.sh"
    if curl_rc(base + "/instalar.sh" + buster(base), tmp, 120) != 0:
        return False
    txt = open(tmp, encoding="utf-8", errors="ignore").read()
    if "# Free games catalog installer" not in txt or len(txt) < 20000:
        log("UPDATE: downloaded installer looks wrong, ignoring it")
        return False
    if subprocess.run(["bash", "-n", tmp]).returncode != 0:
        log("UPDATE: downloaded installer has a syntax error, ignoring it")
        return False
    env = dict(os.environ, CATALOG_NO_RESTART="1")
    return subprocess.run(["bash", tmp], env=env).returncode == 0


def update_lists(base):
    good = failed = 0
    for path in list_files():
        name = os.path.basename(path)
        tmp = "/tmp/catalog_" + name
        if curl_rc(base + "/" + name + buster(base), tmp, 120) != 0:
            log("UPDATE FAILED to download %s (kept the old list)" % name)
            failed += 1
            continue
        n = bad = 0
        for rec, ok in read_list(tmp):
            n += ok
            bad += (not ok)
        if n == 0:
            log("UPDATE SKIPPED %s: no valid lines (kept the old list)" % name)
            failed += 1
            continue
        shutil.move(tmp, path)
        log("UPDATED %s (%d games)%s" % (name, n, " - %d invalid lines ignored" % bad if bad else ""))
        good += 1
    return good, failed


def main():
    base = open(os.path.join(DIR, "base_url.txt")).read().strip()
    show("updating")
    log("UPDATE started")
    if update_code(base):
        log("UPDATE: scripts, images and lists updated")
        ok = True
    else:
        log("UPDATE: could not update the scripts, updating only the lists")
        good, failed = update_lists(base)
        subprocess.run([sys.executable, os.path.join(DIR, "sizes.py")], stdout=subprocess.DEVNULL)
        subprocess.run([sys.executable, os.path.join(DIR, "generate.py")], stdout=subprocess.DEVNULL)
        ok = good > 0
    show("updated" if ok else "updfail", 2)
    reload_menu()


main()
PYEOF

cat > "$DIR/sizes.py" << 'PYEOF'
# Fills /storage/catalog/sizes.json with the sizes of games whose list line has no "size"
import json

from common import *

sizes = load_sizes()
missing = [r for p in list_files() for r, ok in read_list(p) if ok and not size_of(r, sizes)]
print("%d games without a known size" % len(missing))
failures = done = 0
for rec in missing:
    url, err = resolve_url(rec)
    if not url:
        if err == "noint":
            failures += 1
            if failures >= 3:
                log("SIZES: stopped after 3 network failures in a row (no internet?)")
                break
        continue
    failures = 0
    n = total_size(url, probe=True)
    if n:
        sizes[rec["system"] + "/" + slug(rec["label"])] = n
        done += 1
json.dump(sizes, open(SIZES, "w"))
log("SIZES: found %d of %d missing sizes" % (done, len(missing)))
print("sizes found: %d" % done)
PYEOF

for s in nes snes atarilynx atari2600 gba gbc genesis mastersystem c64 zxspectrum n64; do
  curl -L -s -f -o "$DIR/lists/$s.jsonl" "$BASE/$s.jsonl?t=$(date +%s)" || echo "Could not download the $s list"
done
echo "Checking game sizes (this can take a minute the first time)..."
python3 "$DIR/sizes.py"
python3 "$DIR/generate.py"
if [ -z "$CATALOG_NO_RESTART" ]; then
  systemctl restart emustation
fi
echo "Done. Open Ports > Catalog. Use 'Update Catalog' there to refresh the lists and the scripts."
